// Parity tests against packets generated by Mission Planner's own MAVLink.dll
// (tools/make_fixtures.ps1): for all 349 messages, v1 and v2, random and zero-tail payloads.

import XCTest
@testable import MAVLinkKit

struct Fixture: Decodable {
    let id: UInt32
    let name: String
    let variant: Int
    let sysid: UInt8
    let compid: UInt8
    let seq: UInt8
    let v2: String
    let v1: String?
    let fields: [String: FieldValue]
}

enum FieldValue: Decodable {
    case scalar(String)
    case array([String])

    init(from decoder: Decoder) throws {
        let c = try decoder.singleValueContainer()
        if let s = try? c.decode(String.self) { self = .scalar(s) } else { self = .array(try c.decode([String].self)) }
    }

    var strings: [String] {
        switch self {
        case .scalar(let s): return [s]
        case .array(let a): return a
        }
    }
}

/// Same rule as tools/gen_swift.py camel().
func camel(_ name: String) -> String {
    let parts = name.split(separator: "_").map(String.init)
    guard let first = parts.first else { return name }
    return first + parts.dropFirst().map { $0.prefix(1).uppercased() + $0.dropFirst() }.joined()
}

func hexBytes(_ s: String) -> [UInt8] {
    var out = [UInt8]()
    var i = s.startIndex
    while i < s.endIndex {
        let j = s.index(i, offsetBy: 2)
        out.append(UInt8(s[i..<j], radix: 16)!)
        i = j
    }
    return out
}

/// Flattens a decoded field value into comparable strings (integers) / doubles (floats).
func flatten(_ value: Any) -> [Any] {
    if let a = value as? [Any] { return a }
    return [value]
}

func matches(_ value: Any, _ expected: String) -> Bool {
    switch value {
    case let v as Float: return Double(v) == Double(expected)
    case let v as Double: return v == Double(expected)
    case let v as UInt8: return String(v) == expected
    case let v as Int8: return String(v) == expected
    case let v as UInt16: return String(v) == expected
    case let v as Int16: return String(v) == expected
    case let v as UInt32: return String(v) == expected
    case let v as Int32: return String(v) == expected
    case let v as UInt64: return String(v) == expected
    case let v as Int64: return String(v) == expected
    default: return false
    }
}

final class FixtureTests: XCTestCase {
    static let fixtures: [Fixture] = {
        let url = Bundle.module.url(forResource: "mp_packets", withExtension: "json", subdirectory: "Fixtures")!
        return try! JSONDecoder().decode([Fixture].self, from: Data(contentsOf: url))
    }()

    func testFixturesLoaded() {
        XCTAssertEqual(Self.fixtures.count, 698)
    }

    func testEveryMessageDecodesAndReencodesIdenticallyToMissionPlanner() {
        var checked = 0
        for fx in Self.fixtures {
            let encodings: [(MAVLinkPacket.Version, String?)] = [(.v2, fx.v2), (.v1, fx.v1)]
            for (version, hex) in encodings {
                guard let hex = hex else { continue }
                let raw = hexBytes(hex)
                let parser = MAVLinkParser()
                let packets = parser.parse(raw)
                guard packets.count == 1, let p = packets.first else {
                    XCTFail("\(fx.name) v\(version.rawValue) variant \(fx.variant): parsed \(packets.count) packets")
                    continue
                }
                XCTAssertEqual(p.version, version)
                XCTAssertEqual(p.messageID, fx.id)
                XCTAssertEqual(p.systemID, fx.sysid)
                XCTAssertEqual(p.componentID, fx.compid)
                XCTAssertEqual(p.sequence, fx.seq)
                XCTAssertEqual(p.raw, raw)

                guard let msg = p.decode() else { XCTFail("\(fx.name): no decoder"); continue }
                XCTAssertEqual(type(of: msg).mavInfo.name, fx.name)

                // field-by-field comparison with the values Mission Planner encoded
                let mirror = Mirror(reflecting: msg)
                var seen = 0
                for (snake, expected) in fx.fields {
                    guard let child = mirror.children.first(where: { $0.label == camel(snake) }) else {
                        XCTFail("\(fx.name).\(snake): missing property \(camel(snake))"); continue
                    }
                    let got = flatten(child.value)
                    let want = expected.strings
                    XCTAssertEqual(got.count, want.count, "\(fx.name).\(snake) length")
                    for (g, w) in zip(got, want) where !matches(g, w) {
                        XCTFail("\(fx.name).\(snake) v\(version.rawValue): got \(g), want \(w)")
                        break
                    }
                    seen += 1
                }
                XCTAssertEqual(seen, mirror.children.count, "\(fx.name): property count")

                // re-encode and require identical bytes
                let info = type(of: msg).mavInfo
                let payload: [UInt8] = {
                    var w = MAVLinkPayloadWriter(length: info.length)
                    msg.encode(into: &w)
                    return w.bytes
                }()
                let mine: [UInt8]? = version == .v2
                    ? MAVLinkFraming.encodeV2(messageID: info.id, crcExtra: info.crcExtra, payload: payload,
                                              sequence: fx.seq, systemID: fx.sysid, componentID: fx.compid)
                    : MAVLinkFraming.encodeV1(messageID: info.id, crcExtra: info.crcExtra, payload: payload,
                                              sequence: fx.seq, systemID: fx.sysid, componentID: fx.compid)
                XCTAssertEqual(mine, raw, "\(fx.name) v\(version.rawValue) variant \(fx.variant): encoding differs from Mission Planner")
                checked += 1
            }
        }
        XCTAssertEqual(checked, 1086)
    }

    func testStreamWithNoiseFakeStartBytesAndOddChunking() {
        var stream: [UInt8] = []
        var expected = 0
        // a corrupted copy first: must be rejected without losing what follows
        var corrupted = hexBytes(Self.fixtures[0].v2)
        corrupted[12] ^= 0xFF
        stream += corrupted
        for fx in Self.fixtures {
            for hex in [fx.v2, fx.v1].compactMap({ $0 }) {
                stream += [0x00, 0x55, 0xFD, 0x07, 0x00] + hexBytes(hex)
                expected += 1
            }
        }
        let parser = MAVLinkParser()
        var got = 0
        var i = 0
        while i < stream.count {
            let end = min(i + 37, stream.count)
            got += parser.parse(Array(stream[i..<end])).count
            i = end
        }
        XCTAssertEqual(got, expected)
        XCTAssertGreaterThanOrEqual(parser.stats.crcErrors, 1)
    }
}
